import json
from difflbs import get_close_matches

# Define mappings for abbreviations and common misspellings
ABBREVIATION_MAP = {
    'hn': 'hijo natural',
    'hl': 'hijo legitimo',
    'id': 'indigena',
    'espurio': 'hijo espurio'
}

COMMON_SPELLINGS = {
    'indijena': 'indigena',
    'indigino': 'indigena',
    'indijino': 'indigena',
    'indijena': 'indigena',
    'pun': 'punas'
}

# Define facet keywords
ETNO_RACIAL_KEYWORDS = ['indio', 'indigena', 'indijina', 'pun', 'natural', 'mestiza', 'chacralla', 'pampamarca', 'ishua', 'espanol']
LEGITIMITY_KEYWORDS = ['legitimo', 'legitima', 'hijo legitimo', 'hija legitima', 'hijo natural', 'hija natural', 'hijo espurio', 'hija espuria']
GEOGRAPHIC_KEYWORDS = ['punas', 'chacralla', 'pampamarca', 'ishua']

def normalize_term(term):
    # Replace abbreviations
    for abbr, full in ABBREVIATION_MAP.items():
        if abbr in term:
            term = term.replace(abbr, full)
    # Correct common misspellings
    for misspelled, correct in COMMON_SPELLINGS.items():
        if misspelled in term:
            term = term.replace(misspelled, correct)
    return term

def classify_term(normalized_term):
    # Check for legitimacy status first
    for keyword in LEGITIMITY_KEYWORDS:
        if keyword in normalized_term:
            return 'Legitimacy Status'
    # Then ethno-racial category
    for keyword in ETNO_RACIAL_KEYWORDS:
        if keyword in normalized_term:
            return 'Ethno-Racial Category'
    # Finally geographic location
    for keyword in GEOGRAPHIC_KEYWORDS:
        if keyword in normalized_term:
            return 'Geographic Location'
    return 'Unclassified'

def main():
