        "hn,hl hijo,hl hija,hl,indio,aucara,legitima,espanol,indo indio,indo,natural aucara,natural,hijo,hijo espurio,espurio",
        "hijo espurio,india,id,hn,hl hijo,hl hija,hl,hijos,hijo natural,hijo legitimo,id chacralla,vecino id,legitimo,natural,legitima",
        "indijino,indigena,legitimo india,legitimo espanol,indios,legitimo indigena,hija,ishua,natural,espanol,legitimo hija,legitimo natural,hijo legitimo,hijo,legitimo",
        "ishua,hl hijo,indigena,indo indio,indo,chacralla,indio ishua,pampamarca,indio chacralla,indio pampamarca,hijo,legitimo indio,hijo legitimo,legitimo,indio",
        "naturales,legitimos,hijo legitima,hl,legitima indio,legitima espanola,aucara,legitima natural,hija espuria,padre,espanola,espuria,hija legitima,legitima,hija",
        "indio pampamarca,indijina,natural indijina,chacralla,natural indigena,pampamarca,natural hija,chacralla hijo,espanol,natural natural,natural indio,indio,hijo,natural,hijo natural"
